// Los HTTP pueden traer la lista partida en items o en un solo item: la desenvolvemos
function desenvolver(nodo) {
  const bruto = nodo.all().map(i => i.json);
  const lista = [];
  for (const b of bruto) {
    if (Array.isArray(b)) { for (const x of b) lista.push(x); }
    else if (b && b.id) { lista.push(b); }
  }
  return lista.filter(x => x && typeof x.importe === 'number');
}

const ventas = desenvolver($('Ventas de hoy'));
const abonos = desenvolver($('Abonos de hoy'));

function sumarPorForma(items) {
  const por = {};
  for (const it of items) por[it.forma_pago] = (por[it.forma_pago] || 0) + it.importe;
  return por;
}

const vPor = sumarPorForma(ventas);
const aPor = sumarPorForma(abonos);
const totalVentas = ventas.reduce((s, x) => s + x.importe, 0);
const totalAbonos = abonos.reduce((s, x) => s + x.importe, 0);
const total = totalVentas + totalAbonos;

const formas = ['efectivo', 'tarjeta', 'bizum'];
const lineas = [];

lineas.push('VENTAS DIRECTAS (' + ventas.length + '):');
if (ventas.length === 0) {
  lineas.push('  (ninguna)');
} else {
  for (const f of formas) if (vPor[f]) lineas.push('  ' + f + ': ' + vPor[f].toFixed(2) + ' EUR');
  lineas.push('  Total ventas: ' + totalVentas.toFixed(2) + ' EUR');
}

lineas.push('');
lineas.push('ABONOS DE APARTADOS (' + abonos.length + '):');
if (abonos.length === 0) {
  lineas.push('  (ninguno)');
} else {
  for (const f of formas) if (aPor[f]) lineas.push('  ' + f + ': ' + aPor[f].toFixed(2) + ' EUR');
  lineas.push('  Total abonos: ' + totalAbonos.toFixed(2) + ' EUR');
}

lineas.push('');
lineas.push('TOTAL COBRADO HOY: ' + total.toFixed(2) + ' EUR');
if (ventas.length === 0 && abonos.length === 0) {
  lineas.push('(Hoy no se ha cobrado nada.)');
}

const resumen = lineas.join('\n');
const fecha = $now.toFormat('dd/MM/yyyy');

// Tu texto original, pero con saltos de línea reales
const asunto = 'Cierre de caja del ' + fecha;
const texto = 'Hola Marisa,\n\n'
  + 'Resumen de hoy:\n\n'
  + resumen + '\n\n'
  + 'Zapatería Paso Firme';

return [{
  json: {
    fecha: fecha,
    total: total.toFixed(2),
    resumen: resumen,
    asunto: asunto,
    texto: texto
  }
}];
